  <div className="dashboard-lower"><section className="panel"><SectionTitle eyebrow="LEAGUE STANDINGS" title="リーグの現在地" action="全成績を見る" onClick={()=>goto('stats')}/><Standings season={state.season} state={state} compact/></section><section className="panel"><SectionTitle eyebrow="CLUB NEWS" title="クラブ通信"/><div className="news-list"><News icon={<Gift size={18}/>} tag="WELCOME BONUS" title="スタートダッシュ、準備完了。" body="24選手と15,000ジェムで理想のチームづくり。"/><News icon={<BarChart3 size={18}/>} tag="REAL PLAYER DATA" title="2026年9月20日、最新実績を収録。" body={`支配下・育成を含む${players.length.toLocaleString()}人。全5能力をカードで比較できます。`}/><News icon={<Trophy size={18}/>} tag="SEASON REWARD" title="走り切った先に、新しい出会い。" body="1試合75ジェム。完走で3,000ジェム＋UR確定チケット。"/></div></section></div>
