function Metric({label,value,unit,foot,icon,bar}:{label:string;value:string;unit:string;foot:string;icon:ReactNode;bar?:number}){return <div className="metric"><div className="metric-label">{label}<span>{icon}</span></div><div className="metric-number">{value}<span>{unit}</span></div><div className="metric-foot">{foot}</div>{bar!==undefined&&<div className="metric-bar"><i style={{width:`${bar}%`}}/></div>}</div>;}
function SectionTitle({eyebrow,title,action,onClick}:{eyebrow:string;title:string;action?:string;onClick?:()=>void}){return <div className="section-title"><div><div className="eyebrow">{eyebrow}</div><h2>{title}</h2></div>{action&&<button className="text-button" onClick={onClick}>{action}<ArrowUpRight size={14}/></button>}</div>;}
function News({icon,tag,title,body}:{icon:ReactNode;tag:string;title:string;body:string}){return <div className="news-item"><span className="news-icon">{icon}</span><div><small>{tag}</small><h3>{title}</h3><p>{body}</p></div></div>;}
function Standings({season,state,compact=false}:{season:Season;state:GameState;compact?:boolean}){
 const [league,setLeague]=useState(teamById(state.club).league);const rows=rankings(season,league);
 return <><div className="segments league-tabs"><button className={league==='CENTRAL'?'active':''} onClick={()=>setLeague('CENTRAL')}>セ・リーグ</button><button className={league==='PACIFIC'?'active':''} onClick={()=>setLeague('PACIFIC')}>パ・リーグ</button></div><div className="table-scroll"><table className="data-table standings"><thead><tr><th>順位</th><th>チーム</th><th>勝</th><th>敗</th>{!compact&&<th>分</th>}<th>勝率</th>{!compact&&<><th>差</th><th>得失点</th><th>直近5試合</th></>}</tr></thead><tbody>{rows.map((t,i)=><tr key={t.team} className={t.team===state.club?'my-row':''}><td><span className={i===0&&season.day?'rank-first':''}>{season.day?String(i+1).padStart(2,'0'):'—'}</span></td><td><TeamMark id={t.team} mine={t.team===state.club}/><strong>{t.team===state.club?state.name:teamById(t.team).short}</strong>{t.team===state.club&&<small className="you">YOU</small>}</td><td>{t.w}</td><td>{t.l}</td>{!compact&&<td>{t.d}</td>}<td>{season.day?winPct(t).toFixed(3).replace(/^0/,''):'—'}</td>{!compact&&<><td>{i===0?'—':((rows[0].w-t.w+t.l-rows[0].l)/2).toFixed(1)}</td><td>{t.rf-t.ra>0?'+':''}{t.rf-t.ra}</td><td><div className="form">{t.form.map((r,i)=><span className={r} key={i}>{r}</span>)}</div></td></>}</tr>)}</tbody></table></div></>;
}
function SeasonPage({state,advance,onNext,onGame,onStats}:{state:GameState;advance:(n:number)=>void;onNext:()=>void;onGame:(g:GameResult)=>void;onStats:()=>void}){
 const season=state.season;const [limit,setLimit]=useState(15);const next=schedule[Math.min(season.day,142)].find(pair=>pair.includes(state.club))!;const opponent=next.find(id=>id!==state.club)!;
 return <><div className="season-actions panel"><div><div className="eyebrow">{season.completed?'SEASON COMPLETE':'NEXT GAME'}</div><h2>{season.completed?'レギュラーシーズン、終了。':`${state.name} vs ${teamById(opponent).short}`}</h2><p>{season.completed?'日本一への道は上の短期決戦から。':`第${season.day+1}戦 · ${next[0]===state.club?'HOME':'AWAY'} · ${season.day>=45&&season.day<63?'セ・パ交流戦':'リーグ公式戦'}`}</p></div><div className="advance-buttons">{season.completed?<><button className="btn outline" onClick={onStats}>成績を見る</button>{season.postseason?.stage==='complete'&&<button className="btn primary" onClick={onNext}>次のシーズンへ<ArrowRight size={17}/></button>}</>:<><button className="btn outline" onClick={()=>advance(1)}><Play size={15}/>1試合</button><button className="btn outline" onClick={()=>advance(30)}>30試合<ChevronsRight size={16}/></button><button className="btn primary" onClick={()=>advance(143)}><ChevronsRight size={17}/>シーズン終了まで</button></>}</div></div><div className="season-timeline"><span>OPENING DAY</span><div><i style={{width:`${season.day/143*100}%`}}/><b style={{left:`${Math.min(97,season.day/143*100)}%`}}>{season.day}</b></div><span>143 GAMES</span></div><section className="panel"><SectionTitle eyebrow="PENNANT RACE" title={`SEASON ${String(season.number).padStart(2,'0')} リーグ順位`}/><Standings season={season} state={state}/></section><section className="panel"><SectionTitle eyebrow="GAME RESULTS" title="試合結果"/>{season.results.length?<><div className="match-list">{[...season.results].reverse().slice(0,limit).map(g=>{const home=g.home===state.club;const score=home?g.homeRuns:g.awayRuns;const opp=home?g.awayRuns:g.homeRuns;return <button className="match-row" key={g.day} onClick={()=>onGame(g)}><small>GAME {String(g.day).padStart(3,'0')}</small><span className={`result-badge ${score>opp?'W':score<opp?'L':'D'}`}>{score>opp?'WIN':score<opp?'LOSE':'DRAW'}</span><span>{home?'HOME':'AWAY'}</span><strong>{state.name}</strong><b>{score}<i>−</i>{opp}</b><strong>{teamById(home?g.away:g.home).short}</strong><ChevronRight size={16}/></button>;})}</div>{limit<season.results.length&&<button className="btn outline load-more" onClick={()=>setLimit(l=>l+30)}>さらに表示</button>}</>:<Empty title="開幕のサイレンを、鳴らそう。" text="試合を進めると、ここにスコアとイニング別の結果が並びます。"/>}</section></>;
}
function Empty({title,text}:{title:string;text:string}){return <div className="empty-state"><Diamond size={31}/><h3>{title}</h3><p>{text}</p></div>;}
function TeamPage({state,setState,onPlayer,notify}:{state:GameState;setState:(s:GameState)=>void;onPlayer:(p:Player)=>void;notify:(s:string)=>void}){
 const [kind,setKind]=useState<'bat'|'pit'>('bat');const [slot,setSlot]=useState<number|null>(null);const [search,setSearch]=useState('');
 const ids=kind==='bat'?state.lineup:state.pitchers;const eligible=Object.keys(state.owned).map(id=>playerMap[id]).filter(p=>(kind==='bat'?canBat(p):p.role==='pitcher')&&matchesPlayerName(p,search)).sort((a,b)=>effectiveOverall(b,state.owned,state.training)-effectiveOverall(a,state.owned,state.training));
 const assign=(id:string)=>{if(slot===null)return;const next=[...ids];const prev=next.indexOf(id);if(prev>=0)next[prev]=next[slot];const oldId=next[slot];next[slot]=id;const defense={...state.defense};if(kind==='bat'){defense[id]=state.defense[oldId];if(prev>=0)defense[oldId]=state.defense[id];else delete defense[oldId];}setState({...state,defense,[kind==='bat'?'lineup':'pitchers']:next});setSlot(null);notify(`${playerMap[id].name}を編成しました。`);};
 const swapPosition=(id:string,pos:string)=>{const other=state.lineup.find(p=>p!==id&&state.defense[p]===pos);if(!other)return;setState({...state,defense:{...state.defense,[id]:pos,[other]:state.defense[id]}});};
 const move=(i:number,d:number)=>{if(i+d<0||i+d>=ids.length)return;const next=[...ids];[next[i],next[i+d]]=[next[i+d],next[i]];setState({...state,[kind==='bat'?'lineup':'pitchers']:next});};
 return <><BenchAdvice state={state} onEquip={id=>{setState(equipScoutedPlayer(state,id));notify(`${playerMap[id].name}を起用しました。`);}}/><div className="team-toolbar"><div className="segments"><button className={kind==='bat'?'active':''} onClick={()=>{setKind('bat');setSlot(null);}}>野手オーダー</button><button className={kind==='pit'?'active':''} onClick={()=>{setKind('pit');setSlot(null);}}>投手陣</button></div><button className="btn outline" onClick={()=>{setState(buildByStrategy(state,"balanced"));notify("育成・覚醒・守備適性を考慮して自動編成しました。");}}><Shuffle size={16}/>おまかせ編成</button></div><div className="team-layout"><section className="panel order-panel"><SectionTitle eyebrow={kind==='bat'?'STARTING LINEUP':'PITCHING STAFF'} title={kind==='bat'?'スターティングオーダー':'先発6人 + 救援8人'}/><p className="fine-print">{kind==='bat'?'行の「入替」で選手を変更。矢印で打順を変更できます。守備位置の選択欄で位置を交換できます。適性外だと守備補正が下がります。':'先発は6人でローテーション。救援は中継ぎ6人・セットアッパー1人・抑え1人。先発のスタミナと失点、試合展開によって継投します。'}</p><div className="order-list">{ids.map((id,i)=>{const p=playerMap[id];const fit=kind==='pit'||fitsPosition(p,state.defense[id]);return <div className={`order-row ${slot===i?'selected':''}`} key={`${i}-${id}`}><span className="order-no">{i+1}</span>{kind==='bat'?<select className={`position-picker ${fit?'':'mismatch'}`} aria-label={`${p.name}の守備位置`} value={state.defense[id]} onChange={e=>swapPosition(id,e.target.value)}>{[...new Set(rosterSlots)].map(pos=><option key={pos}>{pos}</option>)}</select>:<span className="position-label">{i<6?'先発':i===13?'抑え':i===12?'セット':'中継'}</span>}<TeamMark id={p.team}/><button data-player-id={p.id} className="player-name-button" onClick={()=>onPlayer(p)}><strong>{p.name}</strong><small>{teamById(p.team).short} {!fit&&'· 適性外'}</small></button><span className={`rarity-label ${p.rarity}`}>{p.rarity}</span><b className="overall-small">{effectiveOverall(p,state.owned,state.training)}</b><div className="order-arrows"><button disabled={i===0} onClick={()=>move(i,-1)} aria-label={`${p.name}を上へ`}><ArrowUp size={12}/></button><button disabled={i===ids.length-1} onClick={()=>move(i,1)} aria-label={`${p.name}を下へ`}><ArrowDown size={12}/></button></div><button className="swap-button" onClick={()=>setSlot(slot===i?null:i)}>{slot===i?'取消':'入替'}</button></div>;})}</div></section><section className="panel bench-panel"><SectionTitle eyebrow="YOUR PLAYERS" title={slot===null?'獲得済みの選手':`${kind==='bat'?`${slot+1}番`:`投手枠${slot+1}`}の選手を選択`}/><label className="search-box"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="選手名で検索" aria-label="所持選手を検索"/></label>{slot===null&&<p className="small-muted">左の「入替」を選ぶと、ここから選手を編成できます。</p>}<div className="bench-list">{eligible.map(p=><button data-player-id={p.id} key={p.id} className="bench-row" onClick={()=>slot===null?onPlayer(p):assign(p.id)}><TeamMark id={p.team}/><span><strong>{p.name}</strong><small>{p.positions.join(' / ')||'DH'} · {p.rarity}</small></span><b>{effectiveOverall(p,state.owned,state.training)}</b>{ids.includes(p.id)?<small className="in-lineup">編成中</small>:<Plus size={15}/>}</button>)}</div></section></div></>;
}
function Collection({state,onPlayer}:{state:GameState;onPlayer:(p:Player)=>void}){
 const [query,setQuery]=useState('');const [club,setClub]=useState('all');const [rarity,setRarity]=useState('all');const [role,setRole]=useState('all');const [ownedOnly,setOwnedOnly]=useState(false);const [registration,setRegistration]=useState('all');const [limit,setLimit]=useState(30);
 const collectionPool=ownedOnly?Object.keys(state.owned).map(id=>playerMap[id]):players;
 const list=collectionPool.filter(p=>(club==='all'||p.team===club)&&(rarity==='all'||p.rarity===rarity)&&(role==='all'||(role==='batter'?canBat(p):p.role==='pitcher'))&&(registration==='all'||p.roster?.registration===registration)&&(!ownedOnly||state.owned[p.id])&&matchesPlayerName(p,query)).sort((a,b)=>b.overall-a.overall);
 return <><div className="collection-heading"><p className="muted">支配下から育成まで、NPB全{players.length.toLocaleString()}人。</p><strong>{players.filter(p=>state.owned[p.id]).length}<span> / {players.length} COLLECTED</span></strong></div><div className="roster-coverage"><div><span>NPB公式名簿 · {rosterInfo.asOf}現在</span><strong>支配下 {rosterCoverage.registered}人 <i>＋</i> 育成 {rosterCoverage.developmental}人</strong><small>一軍成績の有無にかかわらず全員を収録。未収録の実績は「—」で表示。</small>{Object.keys(state.owned).some(id=>!playerMap[id].active)&&<small>全所持 {Object.keys(state.owned).length}種類。うち旧年度・旧所属カード {Object.keys(state.owned).filter(id=>!playerMap[id].active).length}種類も保存済み。「所持のみ」で確認できます。</small>}</div><details><summary>球団ごとの収録人数</summary><div className="roster-team-counts">{rosterInfo.sources.map(s=>{const t=teams.find(t=>s.url.endsWith(`rst_${t.id}.html`))!;return <button key={t.id} onClick={()=>{setClub(t.id);setLimit(30);}}><b>{t.short}</b><span>{s.count}人</span><small>支配下{s.registered} / 育成{s.developmental}</small></button>;})}</div></details></div><div className="filter-bar"><label className="search-box"><Search size={17}/><input value={query} onChange={e=>{setQuery(e.target.value);setLimit(30);}} placeholder="選手名で検索" aria-label="選手名で検索"/></label><select value={club} onChange={e=>{setClub(e.target.value);setLimit(30);}} aria-label="球団で絞り込む"><option value="all">すべての球団</option>{teams.map(t=><option value={t.id} key={t.id}>{t.short}</option>)}</select><select value={rarity} onChange={e=>{setRarity(e.target.value);setLimit(30);}} aria-label="レアリティ"><option value="all">全レアリティ</option>{rarityOrder.map(r=><option key={r}>{r}</option>)}</select><select value={role} onChange={e=>{setRole(e.target.value);setLimit(30);}} aria-label="野手・投手"><option value="all">野手・投手</option><option value="batter">野手</option><option value="pitcher">投手</option></select><select aria-label="登録区分" value={registration} onChange={e=>{setRegistration(e.target.value);setLimit(30);}}><option value="all">支配下・育成すべて</option><option value="registered">支配下選手</option><option value="developmental">育成選手</option></select><label className="owned-toggle"><input type="checkbox" checked={ownedOnly} onChange={e=>{setOwnedOnly(e.target.checked);setLimit(30);}}/>所持のみ</label></div><div className="result-count">{list.length} PLAYERS <span>総合力順</span></div><div className="collection-grid">{list.slice(0,limit).map(p=><div key={p.id}><PlayerCard player={p} owned={state.owned[p.id]} training={state.training[p.id]??0} onClick={()=>onPlayer(p)}/><div className="collection-card-caption">{state.owned[p.id]?<span><Check size={12}/>所持 {state.owned[p.id]}枚</span>:<span>未獲得</span>}<span>{p.provisional?'実績未収録 · 暫定':p.role==='batter'?`打率 ${p.batting?.ab?formatAvg(p.batting.avg):'—'}`:`防御率 ${p.pitching?.outs?p.pitching.era.toFixed(2):'—'}`}</span></div></div>)}</div>{!list.length&&<Empty title="該当する選手が見つかりません。" text="選手名や絞り込み条件を変更してください。"/>}{list.length>limit&&<button className="btn outline load-more" onClick={()=>setLimit(l=>l+30)}>さらに30人を見る<ChevronDown size={16}/></button>}</>;
}
function StatsPage({state,onPlayer,onSeason}:{state:GameState;onPlayer:(p:Player)=>void;onSeason:()=>void}){
 const [archive,setArchive]=useState(0);const [mode,setMode]=useState<'bat'|'pit'>('bat');const [scope,setScope]=useState('mine');const [sort,setSort]=useState('hr');const [qualified,setQualified]=useState(false);const [limit,setLimit]=useState(30);
 const season=archive===0?state.season:state.history.find(s=>s.number===archive)??state.season;const mine=season.standings.find(t=>t.team===state.club)!;const rank=rankings(season,teamById(state.club).league).findIndex(t=>t.team===state.club)+1;
 const batting=Object.values(season.batting).filter(s=>(scope==='all'||s.team===state.club)&&(!qualified||s.pa>=Math.round(season.day*3.1))).sort((a,b)=>sort==='avg'?battingAverage(b)-battingAverage(a):sort==='ops'?ops(b)-ops(a):(b[sort as keyof BatStats] as number)-(a[sort as keyof BatStats] as number));
 const pitching=Object.values(season.pitching).filter(s=>(scope==='all'||s.team===state.club)&&(!qualified||s.outs>=season.day*3)).sort((a,b)=>sort==='era'?(a.outs?era(a):Infinity)-(b.outs?era(b):Infinity):(b[sort as keyof PitStats] as number)-(a[sort as keyof PitStats] as number));
 const topBat=Object.values(season.batting).filter(s=>s.team===state.club).sort((a,b)=>b.hr-a.hr)[0];const topPit=Object.values(season.pitching).filter(s=>s.team===state.club).sort((a,b)=>b.so-a.so)[0];
 return <><div className="stats-toolbar"><div><strong>ゲーム内シミュレーション成績</strong><span> · 実際の2026年成績は選手図鑑で確認できます</span></div><select value={archive} onChange={e=>{setArchive(Number(e.target.value));setLimit(30);}} aria-label="表示シーズン"><option value={0}>SEASON {state.season.number}（現在）</option>{state.history.map(s=><option key={s.number} value={s.number}>SEASON {s.number}（終了）</option>)}</select></div>{!season.day?<section className="panel"><Empty title="まだ、記録のないシーズン。" text="試合を進めると打率・本塁打・OPS・防御率などを集計します。"/><button className="btn primary load-more" onClick={onSeason}>シーズンへ<ArrowRight size={17}/></button></section>:<><div className={`season-summary ${season.completed?'completed':''}`}><div className="summary-icon"><Trophy size={42}/></div><div><div className="eyebrow light">{season.completed?'FINAL SEASON REPORT':'SEASON REPORT'}</div><h2>{season.completed&&rank===1?'リーグ優勝、おめでとう。':`${state.name}のシーズンレポート`}</h2><p>{season.day}試合 · {mine.w}勝 {mine.l}敗 {mine.d}分 · 勝率 {winPct(mine).toFixed(3)}</p></div><div className="summary-rank"><strong>{rank}</strong><span>LEAGUE RANK</span></div></div><div className="record-highlights"><div><small>TEAM HOME RUN LEADER</small><strong>{topBat?playerMap[topBat.playerId].name:'—'}</strong><b>{topBat?.hr??0}<span>本塁打</span></b></div><div><small>TEAM STRIKEOUT LEADER</small><strong>{topPit?playerMap[topPit.playerId].name:'—'}</strong><b>{topPit?.so??0}<span>奪三振</span></b></div><div><small>RUN DIFFERENTIAL</small><strong>得失点差</strong><b>{mine.rf-mine.ra>0?'+':''}{mine.rf-mine.ra}<span>{mine.rf}得点 / {mine.ra}失点</span></b></div></div><section className="panel"><SectionTitle eyebrow="SEASON TRAJECTORY" title="順位の推移"/><div className="trend-chart"><div className="trend-labels">{[1,2,3,4,5,6].map(i=><span key={i}>{i}位</span>)}</div><svg viewBox="0 0 1000 130" preserveAspectRatio="none" role="img" aria-label="シーズン中のリーグ順位の推移">{[0,1,2,3,4,5].map(i=><line key={i} x1="0" x2="1000" y1={i*23+7} y2={i*23+7} stroke="#e5e9e2" strokeDasharray="4 4"/>)}<polyline points={season.trend.map((v,i)=>`${i/Math.max(1,season.trend.length-1)*1000},${(v-1)*23+7}`).join(' ')} fill="none" stroke="#1b7058" strokeWidth="2.5" vectorEffect="non-scaling-stroke"/></svg></div><div className="chart-x"><span>開幕</span><span>第{season.day}戦</span></div></section><section className="panel"><SectionTitle eyebrow="PLAYER STATISTICS" title="個人成績ランキング"/><div className="stats-filters"><div className="segments"><button className={mode==='bat'?'active':''} onClick={()=>{setMode('bat');setSort('hr');}}>打撃成績</button><button className={mode==='pit'?'active':''} onClick={()=>{setMode('pit');setSort('era');}}>投手成績</button></div><select value={scope} onChange={e=>setScope(e.target.value)} aria-label="成績の集計対象"><option value="mine">マイチーム</option><option value="all">12球団全選手</option></select><select value={sort} onChange={e=>setSort(e.target.value)} aria-label="成績の並び順">{(mode==='bat'?[['hr','本塁打'],['avg','打率'],['rbi','打点'],['hits','安打'],['sb','盗塁'],['ops','OPS']]:[['era','防御率'],['wins','勝利'],['so','奪三振'],['saves','セーブ'],['outs','投球回']]).map(([key,label])=><option key={key} value={key}>{label}順</option>)}</select><label className="owned-toggle"><input type="checkbox" checked={qualified} onChange={e=>setQualified(e.target.checked)}/>規定{mode==='bat'?'打席':'投球回'}のみ</label></div><div className="table-scroll"><table className="data-table stats-table"><thead><tr><th>#</th><th>選手</th><th>チーム</th>{(mode==='bat'?['試合','打率','本塁打','打点','安打','盗塁','OPS','打席','四球','三振']:['登板','勝','敗','防御率','投球回','奪三振','セーブ','被安打','与四球']).map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{mode==='bat'?batting.slice(0,limit).map((b,i)=><tr key={`${b.team}|${b.playerId}`}><td>{i+1}</td><td><button data-player-id={b.playerId} onClick={()=>onPlayer(playerMap[b.playerId])}>{playerMap[b.playerId].name}</button></td><td>{b.team===state.club?'自チーム':teamById(b.team).short}</td>{[b.games,b.ab?formatAvg(battingAverage(b)):'—',b.hr,b.rbi,b.hits,b.sb,formatAvg(ops(b)),b.pa,b.bb,b.so].map((v,j)=><td key={j} className={j===2?'stat-highlight':''}>{v}</td>)}</tr>):pitching.slice(0,limit).map((p,i)=><tr key={`${p.team}|${p.playerId}`}><td>{i+1}</td><td><button data-player-id={p.playerId} onClick={()=>onPlayer(playerMap[p.playerId])}>{playerMap[p.playerId].name}</button></td><td>{p.team===state.club?'自チーム':teamById(p.team).short}</td>{[p.games,p.wins,p.losses,p.outs?era(p).toFixed(2):'—',formatIP(p.outs),p.so,p.saves,p.hits,p.bb].map((v,j)=><td key={j} className={j===3?'stat-highlight':''}>{v}</td>)}</tr>)}</tbody></table></div>{!(mode==='bat'?batting:pitching).length&&<Empty title="条件に合う成績がありません。" text="規定到達者のみに絞っている場合は、チェックを外してください。"/>}{(mode==='bat'?batting:pitching).length>limit&&<button className="btn outline load-more" onClick={()=>setLimit(l=>l+30)}>さらに表示</button>}<p className="fine-print">規定打席：消化試合×3.1（四捨五入） / 規定投球回：消化試合×1.0。ファンタジー編成のため、自チームと元球団に同じ選手が出場する場合があります。</p></section></>}<section className="panel"><SectionTitle eyebrow="LEAGUE TABLE" title="リーグ順位表"/><Standings season={season} state={state}/></section></>;
}
function GameModal({game,state,close}:{game:GameResult;state:GameState;close:()=>void}){return <Modal onClose={close} wide label="試合のスコア"><div className="eyebrow">GAME {game.day} · MATCH REPORT</div><h2>一試合の、すべての活躍。</h2><GameRecap game={game} state={state}/></Modal>;}
function Settings({state,setState,notify,sound,setSound,onProfileChange}:{onProfileChange?:(profile:Profile)=>void;state:GameState;setState:(s:GameState)=>void;notify:(s:string)=>void;sound:boolean;setSound:(s:boolean)=>void}){
 const [name,setName]=useState(state.name);const input=useRef<HTMLInputElement>(null);
 const download=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`diamond-nine-${isCareer(state)?'career':'free'}-season-${state.season.number}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('セーブデータを書き出しました。');};
 return <div className="settings-layout">{onProfileChange&&<section className="panel career-profile"><div className="eyebrow">PLAY PROFILE</div><h2>{isCareer(state)?"育成モードでプレイ中":"以前のクラブでプレイ中"}</h2><p>育成モードは弱いチーム・0ptから始め、試合でポイントを貯めて選手を集めます。以前のクラブと進行・選手・ポイントは別々に保存されます。</p><button className="btn outline" onClick={()=>onProfileChange(isCareer(state)?"free":"career")}>{isCareer(state)?"以前のクラブに切り替える":"育成モードに切り替える"}<ArrowRight size={16}/></button></section>}<section className="panel"><SectionTitle eyebrow="CLUB SETTINGS" title="あなたのクラブ"/><label className="setting-field">チーム名<div><input maxLength={20} value={name} onChange={e=>setName(e.target.value)}/><button className="btn primary" disabled={!name.trim()} onClick={()=>{setState({...state,name:name.trim()});notify('チーム名を変更しました。');}}>保存</button></div></label><div className="setting-row"><span><strong>スカウトのサウンド</strong><small>獲得演出に短いサウンドを付けます</small></span><button className="btn outline" onClick={()=>setSound(!sound)}>{sound?<Volume2 size={16}/>:<VolumeX size={16}/>} {sound?'ON':'OFF'}</button></div><div className="setting-row"><span><strong>セーブデータ</strong><small>自動保存に加えて、ファイルに保存できます</small></span></div><div className="save-buttons"><button className="btn outline" onClick={download}><Download size={16}/>書き出す</button><button className="btn outline" onClick={()=>input.current?.click()}><Upload size={16}/>読み込む</button><input ref={input} type="file" accept="application/json,.json" hidden onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>10_000_000)throw new Error();const data=migrateState(JSON.parse(await file.text()));if(!data)throw new Error();if(isCareer(data)!==isCareer(state)){notify('別のモードのセーブです。先にモードを切り替えてから読み込んでください。');e.target.value='';return;}setState(data);setName(data.name);notify('セーブデータを読み込みました。');}catch{notify('有効なDIAMOND NINEのセーブデータではありません。');}e.target.value='';}}/></div></section><section className="panel"><SectionTitle eyebrow="HOW TO PLAY" title="3ステップで、黄金時代へ。"/><div className="how-steps">{[['01',isCareer(state)?'試合で貯める':'選手を集める',isCareer(state)?'R中心のチームからスタート。1試合60pt、勝利で＋20pt。300ptで選手を1枚ずつスカウト。5枚目はSR以上、10枚目はSSR以上が確定します。':'スカウトで選手を獲得。ジェムは上部の＋から何度でも無料でもらえます。'],['02','チームをつくる','野手9人、先発6人、救援6人を編成。守備位置と長打力のバランスが勝負のカギ。'],['03','シーズンを楽しむ','1試合・30試合・全143試合を進め、成績を確認。完走後はCS・日本シリーズを戦い、次の年へ進めます。']].map(([n,t,d])=><div key={n}><b>{n}</b><span><strong>{t}</strong><p>{d}</p></span></div>)}</div></section><WikiSourcesPanel/><section className="panel data-note"><SectionTitle eyebrow="ABOUT THE DATA" title="現実の成績と、ゲームの記録"/>
<p>NPB公式名簿（{rosterInfo.asOf}現在）の全{players.length}人を収録。支配下{rosterCoverage.registered}人・育成{rosterCoverage.developmental}人をスカウト・編成できます。実際の一軍成績は{sourceInfo.asOf}現在の球団別記録です。未収録の実績は「—」で表示します。</p>
<p>選手能力はWikiの2026年版を優先し、未掲載の選手・項目には成績や守備実績からの補完査定を使います。2026年の実績を確率の土台とし、掲載能力との差・覚醒・育成・調子を打席ごとの結果へ反映。ミートは安打・三振、パワーは本塁打・長打、走力・肩は進塁と盗塁、守備・捕球・適性は打球処理に作用します。制球は四死球、球速・変化球は奪三振・長打抑止、スタミナは先発の継投に作用します。特殊能力の対応項目と効果は選手詳細で確認できます。</p>
<p>143試合、延長12回まで、両リーグDH制のファンタジー編成です。自チームは兵庫の枠に参加し、獲得選手は元球団にも残ります。試合の安打・本塁打・得点・打点などを集計して打率・OPSを算出。成績はシーズンごとに変動し、終了した試合の記録は査定更新で書き換えません。直近8シーズンを保存します。</p>
<p>選手写真・球団ロゴは使用していません。守備失策・犠打・犠飛・併殺・故障・加齢・トレード、その他の掲載特性の追加効果は未実装です。公式ゲームと同一の動作ではありません。</p>
<div className="source-links"><a href="https://npb.jp/bis/teams/" target="_blank" rel="noreferrer">NPB公式 全選手名簿 ↗</a><a href="https://npb.jp/bis/2026/stats/" target="_blank" rel="noreferrer">NPB公式 2026年度成績 ↗</a><span>NPB成績取得日 {sourceInfo.fetchedAt.slice(0,10)}</span></div></section></div>;
}
